

.invitePromo {
  text-align: center;
  background: url(../../../assets/images/promotion/hotpromo/35/orangeborder.png)
    no-repeat center center;
  background-size: cover;
  padding: 10px;
  height: 100%;
  min-height: 1010px;
  margin: 20px auto 0;
  .table-inv {
    width: 100%;
    overflow: auto;
    tr th {
      background: #db7e42;
      padding: 10px;
    }
    tr {
      &:nth-child(even) {
        background: #2b2b4b;
      }
    }
    tr td {
      padding: 10px;
    }

  }
  .inv-title {
    font-size: 1.5em;
    display: inline-block;
    vertical-align: middle;
    &:before {
      content: "";
      // padding: 5px 30px;
      padding: .4em .8em;
      background: url(../../../assets/images/promotion/hotpromo/35/left.png)
        no-repeat center center;
      background-size: contain;
      display: inline-block;
      vertical-align: middle;
      margin-right: 10px;
    }
    &:after {
      content: "";
      // padding: 5px 30px;
      padding: .4em .8em;
      background: url(../../../assets/images/promotion/hotpromo/35/right.png)
        no-repeat center center;
      background-size: contain;
      display: inline-block;
      vertical-align: middle;
      margin-left: 10px;
    }
  }
}
