
:deep(.ant-table-content) {
    min-width: 400px;
}
.votesm .vote-submit {
  margin: 20px auto 0;
  display: block;
}
.center-numbers {
  gap: 5px;
  position: relative;
  background: url("../../../assets/images/promotion/hotpromo/40/fifa.png")
    no-repeat center center;
  background-size: cover;
  width: 100%;
  min-height: 180px;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  font-family: "Arial";
  .center-title {
    padding-top: 32px;
    font-size: 30px;
    color: #ffffff;
    font-weight: bold;
  }
  .center-number {
    font-size: 50px;
    line-height: 50px;
    font-weight: bold;
    color: #ffffff;
  }
}
.countries-wrapper {
  font-family: "Arial";
  background-color: #290315;
  border-radius: 10px;
  border: solid 1px #a81538;
  max-width: 1298px;
  margin: 50px auto;
  font-size: 16px;
  font-weight: bold;
  padding: 20px;
  .point {
    color: #ffffff;
    &:before {
      content: "";
      width: 8px;
      height: 8px;
      display: inline-block;
      transform: rotateZ(45deg);
      margin-right: 10px;
      background-color: #ff004c;
    }
  }
  .right-count {
    text-align: right;
    color: #ffffff;
    margin-top: 15px;
    font-weight: normal;
  }
  .country-list {
    display: flex;
    gap: 15px;
    padding: 20px 0;
    flex-wrap: wrap;
    justify-content: flex-start;
    .country-item {
      width: 30%;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      padding: 5px;
      background: #ffffff;
      padding: 10px;
      border-radius: 10px;
      overflow: hidden;
      &:hover {
        .c-button {
          background: #a81538;
          color: #ffffff;
        }
      }
      .c-flag {
        background: #eeeee4;
        padding: 10px;
        border-radius: 10px;
        height: 60px;
        width: 100%;
        overflow: hidden;
        display: flex;
        justify-content: center;
        align-items: center;
        img {
          max-width: 100%;
          max-height: 100%;
          border: 1px solid #d4c164;
        }
      }
      .c-name {
        padding: 5px 0;
        color: #a81538;
        text-align: center;
        white-space: nowrap;
        overflow: hidden;
        width: 100%;
        text-overflow: ellipsis;
      }
      .c-price {
        background: #eeeee4;
        color: #000000;
        font-size: 14px;
        font-weight: normal;
        padding: 0 5px;
        border-left: 2px solid #d4c164;
        border-right: 2px solid #d4c164;
        width: 100%;
        text-align: center;
      }
      .c-button {
        border: 2px solid #a81538;
        padding: 2px 10px;
        border-radius: 20px;
        display: block;
        margin-top: 10px;
        width: 100%;
        text-align: center;
        color: #a81538;
        line-height: 16px;
      }
    }
  }
}
.table-details {
  font-family: "Arial";
  background-color: #290315;
  border-radius: 10px;
  border: solid 1px #a81538;
  max-width: 1298px;
  margin: 50px auto;
  font-size: 16px;
  font-weight: bold;
  padding: 20px;
  table {
    width: 100%;

    thead {
      border-bottom: 1px solid #ffffff;
      td {
        text-align: center;
        color: #ffffff;
        padding: 10px;
      }
    }
    tbody {
      border-bottom: 1px solid #ffffff;
      td {
        color: #ffffff;
        padding: 10px;
        text-align: center;
        font-weight: normal;
      }
    }
  }
}
